// Edit before Test workflow: real Chatwoot display_id + account id.
const account_id = 2;
const conversation_id = 0; // conversation display_id from Chatwoot URL
const handoff_reason = 'estudio/precio';
const handoff_quote = 'Quiero saber el precio de un estudio';

if (!conversation_id) {
  throw new Error('Set conversation_id to the Chatwoot display_id before testing.');
}

return [{
  json: {
    telefono: '543816224165',
    account_id,
    conversation_id,
    route: 'hablar_secretaria',
    handoff_reason,
    handoff_quote,
    last_line: handoff_quote,
    texto: handoff_quote,
  }
}];

const n = $('Decide Route').first().json;
return [{
  json: {
    ...n,
    context: {},
    handoff_reason: n.handoff_reason,
    handoff_quote: n.handoff_quote,
  }
}];

const m = $('Decide Route').first().json;
return [{
  json: {
    conversation_id: m.conversation_id,
    account_id: m.account_id,
    cw_body: {
      content: '*Te derivamos con una secretaria. En breve te van a escribir.*',
      message_type: 'outgoing',
      private: false,
      content_type: 'text'
    }
  }
}];

const m = $('Decide Route').first().json;
const ctx = ($('Merge Context').first().json.context) || {};
const reason = m.handoff_reason || ctx.handoff_reason || 'estudio/precio';
const quote = m.handoff_quote || ctx.handoff_quote || m.last_line || m.texto || '';
const teamId = Number($env.CHATWOOT_TEAM_ID);
const teamName = String($env.CHATWOOT_TEAM_NAME || 'Secretaría').trim();
const teamMention = teamId && !Number.isNaN(teamId)
  ? `[@${teamName}](mention://team/${teamId}/${encodeURIComponent(teamName)})`
  : '';
const header = teamMention ? `${teamMention} Derivación a Secretaría` : 'Derivación a Secretaría';
return [{
  json: {
    conversation_id: m.conversation_id,
    account_id: m.account_id,
    cw_body: {
      content: header + '\nMotivo: ' + reason + '\nMensaje del paciente: ' + quote,
      message_type: 'outgoing',
      private: true,
      content_type: 'text'
    }
  }
}];

const m = $('Decide Route').first().json;
const teamId = Number($env.CHATWOOT_TEAM_ID);
if (!teamId || Number.isNaN(teamId)) {
  throw new Error('CHATWOOT_TEAM_ID is missing or invalid on n8n. Set it in .env and recreate n8n.');
}
return [{
  json: {
    conversation_id: m.conversation_id,
    account_id: m.account_id,
    cw_body: {
      team_id: teamId
    }
  }
}];
